5: 
6: class DashboardPage extends StatefulWidget {
7:   const DashboardPage({super.key});
8: 
9:   @override
10:   State<DashboardPage> createState() => _DashboardPageState();
11: }
12: 
13: class _DashboardPageState extends State<DashboardPage> {
14:   static const int _currencyLimit = 5;
15:   static const int _newsLimit = 5;
16: 
17:   late final Future<DashboardData> _dashboardFuture;
18: 
19:   @override
20:   void initState() {
21:     super.initState();
22:     _dashboardFuture = _loadDashboardData();
23:   }
24: 
25:   /// Курс валют и лента новостей запрашиваются параллельно.
26:   Future<DashboardData> _loadDashboardData() async {
27:     final CurrencyRepository currencyRepository = context.read<CurrencyRepository>();
28:     final NewsRepository newsRepository = context.read<NewsRepository>();
29: 
30:     final List<Object> results = await Future.wait(<Future<Object>>[
31:       currencyRepository.fetchRates(const CurrencyPageRequest(pageSize: _currencyLimit)),
32:       newsRepository.loadNewsFeed(const NewsFeedFilter(limit: _newsLimit, forceRefresh: true)),
33:     ]);
34: 
35:     final CurrencyPage currencyPage = results[0] as CurrencyPage;
36:     final List<NewsModel> news = results[1] as List<NewsModel>;
37: 
38:     return DashboardData(currencies: currencyPage.items, news: news);
39:   }
40: 
41:   @override
42:   Widget build(BuildContext context) {
43:     return Scaffold(
44:       appBar: AppBar(
45:         leading: IconButton(
46:           onPressed: () => Navigator.pop(context),
47:           icon: const Icon(Icons.arrow_back),
48:         ),
49:         title: Text(context.loc.dashboard),
50:       ),
51:       body: FutureBuilder<DashboardData>(
52:         future: _dashboardFuture,
53:         builder: (BuildContext context, AsyncSnapshot<DashboardData> snapshot) {
54:           final DashboardData? data = snapshot.data;
55:           if (data == null) {
56:             return const Center(child: CircularProgressIndicator());
57:           }
58: 
59:           return ListView(
60:             padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
61:             children: [
62:               DashboardSectionTitle(title: context.loc.currencyRate),
63:               for (final CurrencyModel currency in data.currencies)
64:                 Padding(
65:                   key: ValueKey<String>(currency.id),
66:                   padding: const EdgeInsets.only(top: 10),
67:                   child: CurrencyCard(model: currency),
68:                 ),
69:               Padding(
70:                 padding: const EdgeInsets.only(top: 24),
71:                 child: DashboardSectionTitle(title: context.loc.news),
72:               ),
73:               for (final NewsModel news in data.news)
74:                 Padding(
75:                   key: ValueKey<String>(news.link),
76:                   padding: const EdgeInsets.only(top: 10),
77:                   child: NewsCard(model: news),
78:                 ),
79:             ],
80:           );
81:         },
82:       ),
83:     );
84:   }
85: }

